/// A `#[repr(transparent)]` newtype over a C type (`Self::C`), together with
/// the borrowed handles that carry its accessors.
///
/// A **linking** trait, not an access trait: it names the wrapped C type and
/// the two handle types. Its only methods are the provided, `unsafe` inbound
/// seam (`ref_from_ptr`, `mut_from_ptr` and their `void *` twins), so
/// implementing it exposes no constructor. ffibox builds the handles from a
/// pointer itself, relying on the layout the contract below guarantees. The
/// outbound seam (`as_ptr` / `as_mut_ptr`) lives on the handles, through
/// [`CRefSeam`] and [`CMutSeam`], because that is where a `&self` receiver is
/// sound — `&FooRef` covers one pointer of Rust stack where `&Foo` would
/// cover the C object.
///
/// Implemented by [`define_ctype!`](crate::define_ctype) for a newtype with no
/// parameters or with lifetimes only, or by hand for a type-generic one. A
/// newtype generic over a lifetime takes its policies from the macros, written
/// `Foo<'_>`, as [`impl_cdrop!`](crate::impl_cdrop) shows.
///
/// # Safety
///
/// - `Self` MUST be layout-compatible with `Self::C`: `#[repr(transparent)]`
///   over it, any other fields zero-sized.
/// - [`Ref<'a>`](CCell::Ref) and [`Mut<'a>`](CCell::Mut) MUST each be
///   `#[repr(transparent)]` over
///   [`CBorrowedPtr<'a, Self>`](crate::CBorrowedPtr) — directly, or `Mut` over
///   `Ref` — with every other field zero-sized and no `Drop`: ffibox builds
///   them from a `CBorrowedPtr` by layout alone. They borrow the pointee for
///   `'a` and MUST NOT hand out a reference to `Self`.
/// - `Ref` MUST NOT offer any operation that writes through the pointer — that
///   is `Mut`'s job, and the split is what keeps a shared borrow shared.
/// - `Mut<'a>` MUST be invariant in `Self`, as `&'a mut Self` is. A
///   [`CBorrowedPtr`](crate::CBorrowedPtr) alone is covariant, like `&'a T`, so
///   add a `PhantomData<&'a mut Self>` field. This matters only when `Self`
======

/// Define a wrapped `*-sys` type: the layout newtype plus its two borrowed
/// handles, and the [`CCell`](crate::CCell) impl linking them.
///
/// ```ignore
/// define_ctype!(Widget, WidgetRef, WidgetMut, ffi::widget_st);
///
/// // A layout type with a lifetime, carried by the `phantom` marker:
/// define_ctype!(Reference<'r>, ReferenceRef, ReferenceMut, ffi::git_reference, phantom = &'r ());
/// ```
///
/// The names are spelled out because `macro_rules!` cannot concatenate
/// identifiers; the order is layout, shared, exclusive. What each type is for
/// is in [docs/borrows.md](https://github.com/crustify-rs/ffibox/blob/main/docs/borrows.md).
///
/// Getters go on `$rf<'a>` taking `&self`, setters on `$mt<'a>` taking
/// `&mut self`, both through the raw seam: [`CRefSeam`](crate::CRefSeam) on
/// `$rf` (`from_ptr`, `as_ptr` and their `void *` twins) and
/// [`CMutSeam`](crate::CMutSeam) on `$mt` (`from_ptr`, `as_mut_ptr` and
/// theirs), which the macro implements. Import them wherever the seam is
/// used, in the invoking crate or any other:
///
/// ```ignore
/// use ffibox::{CMutSeam, CRefSeam};
/// ```
///
/// The inbound half is also on `$name`, through [`CCell`](crate::CCell)
/// (`ref_from_ptr`, `mut_from_ptr` and their twins). Never write an accessor
/// on `$name`: a `&$name` covers the C object's bytes.
///
/// The macro implements no `Debug`, since what a handle prints is the
/// wrapper's: implement it on `$rf`, from its getters, and on `$mt` through
/// `as_ref()`.
///
/// # A layout type with a lifetime
///
====
/// `unsafe impl` of [`CZeroable`](crate::CZeroable).
#[macro_export]
macro_rules! define_ctype {
    (
        @impl [$(#[$attr:meta])*] $name:ident [$($lt:lifetime),*],
        $rf:ident, $mt:ident, $c_type:ty, $marker:ty
    ) => {
        $(#[$attr])*
        #[repr(transparent)]
        pub struct $name<$($lt),*>($c_type, ::core::marker::PhantomData<$marker>);

        #[doc = concat!("Shared borrow of a [`", stringify!($name), "`]. `Copy`, like `&T`; the getters live here.")]
        #[repr(transparent)]
        #[derive(Clone, Copy)]
        pub struct $rf<'a, $($lt),*>($crate::CBorrowedPtr<'a, $name<$($lt),*>>);

        #[doc = concat!("Exclusive borrow of a [`", stringify!($name), "`]. Reaches the getters with [`as_ref`](Self::as_ref); the setters live here.")]
        #[repr(transparent)]
        pub struct $mt<'a, $($lt),*>(
            $rf<'a, $($lt),*>,
            // Invariant in the pointee, as `&'a mut` is; see `CCell`'s contract.
            ::core::marker::PhantomData<&'a mut $name<$($lt),*>>,
        );

        // SAFETY: `$name` is `#[repr(transparent)]` over `$c_type`, its marker
        // zero-sized; the handles are transparent over `CBorrowedPtr<'a, $name>`
        // (`$mt` through `$rf`) with zero-sized markers and no `Drop`, expose no
        // reference to `$name`, and `$mt` is invariant in `$name` through its
        // marker; `$rf` has no write operation of ffibox's.
        unsafe impl<$($lt),*> $crate::CCell for $name<$($lt),*> {
            type C = $c_type;
            type Ref<'a> = $rf<'a, $($lt),*> where Self: 'a;
            type Mut<'a> = $mt<'a, $($lt),*> where Self: 'a;
        }

        // The handles' seams, public to every crate that names the handles.
        impl<'a, $($lt: 'a),*> $crate::CRefSeam<'a> for $rf<'a, $($lt),*> {
            type Cell = $name<$($lt),*>;
        }

        impl<'a, $($lt: 'a),*> $crate::CMutSeam<'a> for $mt<'a, $($lt),*> {

